import json, os
from compose import get_geometric_insights_for_model, GeometricInsights

model_path = os.path.join(os.path.dirname(__file__), 'compose', 'assets', 'compose', 'nakagin-capsule-tower.gltf')
ins = get_geometric_insights_for_model(model_path)
from dataclasses import asdict
raw = asdict(ins)

# convert tuples to lists and drop None fields; round floats to 6 decimals
out = {}
for k, v in raw.items():
    if v is None:
        continue
    if isinstance(v, tuple):
        v = list(v)
    if isinstance(v, list):
        vv = []
        for e in v:
            if isinstance(e, tuple):
                e = list(e)
            if isinstance(e, float):
                e = round(e, 6)
            vv.append(e)
        v = vv
    elif isinstance(v, float):
        v = round(v, 6)
    out[k] = v

print(json.dumps(out, indent=2, sort_keys=True))
